package vn.edu.ltweb.jwtmvc.security; import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter; import java.io.IOException;
@Component public class BearerTokenAuthenticationFilter extends OncePerRequestFilter {final TokenService tokens; public BearerTokenAuthenticationFilter(TokenService t){tokens=t;} protected void doFilterInternal(HttpServletRequest r,HttpServletResponse s,FilterChain c)throws ServletException,IOException{String h=r.getHeader("Authorization");if(h!=null){if(!h.startsWith("Bearer ")){s.setStatus(401);s.setContentType("application/json");s.getWriter().print("{\"status\":401,\"code\":\"UNAUTHORIZED\",\"message\":\"Invalid or expired access token\"}");return;}try{String sub=tokens.extractSubject(h.substring(7));SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(sub,null,java.util.List.of()));}catch(TokenValidationException e){s.setStatus(401);s.setContentType("application/json");s.getWriter().print("{\"status\":401,\"code\":\"UNAUTHORIZED\",\"message\":\"Invalid or expired access token\"}");return;}}c.doFilter(r,s);}}
